#include <iostream>
#include <iomanip>

// C++17 function demonstrating multidimensional array initialization and output
void printMatrix(const int arr[2][3], const char* name) {
    std::cout << name << ":\n";
    for (std::size_t i = 0; i < 2; ++i) {
        for (std::size_t j = 0; j < 3; ++j) {
            std::cout << std::setw(3) << arr[i][j];
        }
        std::cout << "\n";
    }
}

int main() {
    // Sublist initialization
    int array1[2][3] = {{1, 2, 3}, {4, 5, 6}};

    // Flat initialization (unspecified elements zeroed)
    int array2[2][3] = {1, 2, 3, 4, 5};

    // Sublists with missing elements (zeroed by row)
    int array3[2][3] = {{1, 2}, {4}};

    printMatrix(array1, "array1");
    printMatrix(array2, "array2");
    printMatrix(array3, "array3");

    return 0;
}

